put('positioning',rules('positioning','''$ {border:1px solid var(--n-4);border-radius:var(--radius);background:var(--n-1);isolation:isolate}$::before{content:"";position:absolute;left:10%;right:10%;top:50%;border-top:1px dotted var(--n-5)}$::after{content:"";position:absolute;top:14%;bottom:14%;left:50%;border-left:1px dotted var(--n-5)}$>.axis-x{position:absolute;top:calc(50% - 18px);left:var(--gap);right:var(--gap);display:flex;justify-content:space-between;font-size:var(--type-14);z-index:2}$>.axis-y{position:absolute;top:var(--gap);bottom:var(--gap);left:40%;right:40%;display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-14);text-align:center;z-index:2}$>.axis-x>span,$>.axis-y>span{background:var(--n-2);padding:calc(var(--gap-sm)/2) var(--gap-sm);border-radius:999px;color:var(--n-8)}$>.mark{position:absolute;left:calc(15% + var(--x)*.7%);bottom:calc(15% + var(--y)*.7%);width:12px;height:12px;border-radius:50%;background:var(--n-5);transform:translate(-50%,50%);z-index:3}$>.mark>.name{position:absolute;left:50%;bottom:calc(100% + var(--gap-sm));transform:translateX(-50%);font-size:var(--type-16);white-space:nowrap}$>.mark.on{background:var(--a1);width:24px;height:24px;box-shadow:0 0 0 12px var(--a1-2-muted)}$>.mark.on>.name{font-size:var(--type-22);font-weight:var(--name-weight)}$>.mark>.seat.logo{position:absolute;left:50%;bottom:calc(100% + var(--gap-sm));width:54px;height:54px;transform:translateX(-50%)}'''))
put('network',rules('network','''$ {isolation:isolate;padding:var(--gap)}$>.node{position:absolute;left:calc(10% + var(--x)*.8%);top:calc(10% + var(--y)*.8%);width:100px;height:72px;transform:translate(-50%,-50%);border:1px solid var(--n-4);border-radius:var(--radius-sm);background:var(--n-1);display:flex;align-items:center;justify-content:center;text-align:center;padding:var(--gap-sm);z-index:2}$>.node .name{font-size:var(--type-16)}$>.node.on{background:var(--a1);color:var(--a1-on);border-color:var(--a1)}$>.link{position:absolute;left:calc(10% + var(--x1)*.8%);top:calc(10% + var(--y1)*.8%);width:calc(sqrt(pow((var(--x2) - var(--x1))*.8,2) + pow((var(--y2) - var(--y1))*.8,2))*1%);height:1px;background:var(--n-4);transform-origin:left;transform:rotate(atan2(calc(var(--y2) - var(--y1)),calc(var(--x2) - var(--x1))));z-index:-1}$>.link.strong{background:var(--a1);height:2px}@container(max-width:650px){$>.node{width:72px;height:52px}$>.node .name{font-size:var(--type-12)}}'''))
put('code',rules('code','''$ {display:flex;flex-direction:column;border:1px solid var(--n-4);border-radius:var(--radius);padding:var(--pad);background:var(--n-1);gap:var(--gap);overflow:hidden}$>.name{font-size:var(--type-16);padding-bottom:var(--gap-sm);border-bottom:1px dotted var(--n-4)}$>.lines{counter-reset:code;display:flex;flex-direction:column;justify-content:center;flex:1;min-height:0;gap:calc(var(--gap-sm)/3);font-family:var(--font-body);font-size:var(--type-18);font-variant-numeric:tabular-nums;white-space:pre}$>.lines>p{margin:0;counter-increment:code;position:relative}$.numbered>.lines>p{padding-left:var(--pad)}$.numbered>.lines>p::before{content:counter(code);position:absolute;left:0;width:var(--gap);text-align:right;color:var(--n-5)}$ .k{color:var(--a1);font-weight:var(--label-weight)}$ .s{color:var(--a2)}$ .c{color:var(--n-6)}$ .n{color:var(--a3)}@container(max-width:650px){$>.lines{font-size:var(--type-14)}}@container(max-height:300px){$>.lines{font-size:var(--type-12);gap:0}}'''))
for name,body in CSS.items():
 # Palette assignments for ranked variants remain scoped to the documented root.
 variants=rules(name,'$.tone-1{--nightchamfer-rank:var(--a1)}$.tone-2{--nightchamfer-rank:var(--a2)}$.tone-3{--nightchamfer-rank:var(--a3)}$.tone-4{--nightchamfer-rank:var(--a4)}')
 (OUT/'elements'/name/'element.css').write_text(base(name)+body+'\n'+variants+'\n')
missing=set(d.name for d in (OUT/'elements').iterdir())-CSS.keys()
assert not missing,missing
print('built',len(CSS),'elements')
(R/'design-language.md').write_text('''# Nightchamfer 디자인 언어\n\n## replica에서 읽은 규칙\n- 상단 45px 기준선, 오른쪽에서 28px 아래로 한번 접히는 1px 중립 선. 내용은 84~95px 안쪽에서 시작.\n- 패널은 1px 중립 윤곽과 약 22px 모서리. 작은 라벨은 12px, 짧은 카테고리 캡슐은 완전한 알약.\n- 여백 단계 12 / 24 / 28 / 40px. 패널 내부는 가운데에 무게를 두되 제목과 수치는 동일 높이.\n- 기본 서체 Pretendard Variable. 제목 28/44px, 표지 104px, 수치 48/64px, 이름 22px, 본문 16~20px, 보조 12~14px. 제목 700, 본문 400, 라벨 600.\n- 핵심 노드는 두꺼운 저채도 외곽 링과 선명한 원판. 연결선은 1px 점선 또는 절곡선. 화살표는 넓은 단순 실루엣.\n- 강조는 하나의 원판/막대/캡슐에 집중하고 주변은 중립 면. 3D 광택 오브젝트는 내용과 분리된 이미지 자리.\n\n## 색의 자리\n- 페이지 바탕 = --page, 기본 글자 = --ink.\n- 제목 강조·핵심 원판·마지막 막대 = --a1, 그 위 글자 = --a1-on.\n- 핵심 원판의 외곽 링 = --a1-2-muted.\n- 카드 면 = --n-1, 테두리·축 = --n-4, 보조 글 = --n-7.\n- 하단 발광층 = --a1-3-muted에서 투명으로 이어지는 단순 면.\n- 보조 시리즈만 --a2 / --a3 / --a4 순위를 사용.\n- 원본의 검정·파랑을 요소에 고정하지 않고 랭크와 깊이로만 정의.\n\n## 이미지에 없는 요소\n레이더·네트워크·코드 등도 절곡선, 중립 hairline, 짧은 중심 라벨과 하나의 강조를 유지한다. 복잡한 장식은 추가하지 않는다.\n''')
